<template>
<view class="page"><AchievementUnlockNotifier />
 <view v-if="!activeScene"><view class="hero"><text class="title">场景口语</text><text class="subtitle">选择生活场景，完成真实英文对话</text></view>
  <view class="section-heading"><text class="section-title">选择场景</text><text class="section-tip">每个场景 3 轮</text></view>
  <view v-if="loading" class="empty">正在加载场景...</view><view v-else class="scene-list"><view v-for="scene in scenes" :key="scene.id" class="scene-card" @click="startScene(scene)"><view class="scene-icon">{{scene.icon}}</view><view class="scene-info"><text class="scene-name">{{scene.name}}</text><text class="scene-desc">{{scene.description}}</text></view><text class="scene-action">开始 ›</text></view></view>
 </view>
 <view v-else-if="!completed"><view class="practice-head"><view><text class="scene-kicker">{{activeScene.icon}} {{activeScene.name}}</text><text class="round">第 {{currentIndex+1}} / {{rounds.length}} 轮</text></view><text class="exit" @click="exitPractice">退出</text></view><view class="progress"><view class="progress-fill" :style="{width:progress+'%'}"></view></view>
  <view class="conversation-card"><view class="speaker-row"><view class="avatar">🤖</view><text>对方</text></view><text class="prompt-en">{{currentRound.prompt}}</text><text class="prompt-zh">{{currentRound.promptZh}}</text><view class="play-button" @click="playText(currentRound.prompt)">🔊 播放对方的话</view></view>
  <view class="task-card"><text class="task-label">轮到你回答</text><text class="task-zh">请用英文表达：{{currentRound.taskZh}}</text><text class="answer-hint">参考表达：{{currentRound.answer}}</text><view class="record-button" :class="{recording:isRecording,evaluating}" @click="toggleRecord">{{evaluating?'正在评分...':isRecording?`停止并评分（${recordSeconds}秒）`:hasResult&&!passed?'重新回答':'开始回答'}}</view><text v-if="isRecording" class="record-tip">请完整说完参考表达，最长 20 秒</text><view v-if="hasResult" class="result" :class="passed?'passed':'failed'"><view class="result-top"><text>{{passed?'回答通过':'暂未通过'}}</text><text class="score">{{score}}分</text></view><text class="feedback">{{feedback}}</text></view><button v-if="passed" class="next-button" @click="nextRound">{{currentIndex+1===rounds.length?'完成场景':'进入下一轮'}}</button></view>
 </view>
 <view v-else class="complete-card"><view class="complete-icon">🎉</view><text class="complete-title">场景对话完成</text><text class="complete-scene">{{activeScene.icon}} {{activeScene.name}}</text><view class="summary"><view><text>{{rounds.length}}</text><text>完成轮次</text></view><view><text>{{averageScore}}</text><text>平均得分</text></view></view><text class="suggestion">{{summarySuggestion}}</text><button class="primary" @click="backToScenes">继续选择场景</button><button class="secondary" @click="goBack">完成并返回</button></view>
</view>
</template>
<script>
import{request,evaluateSpeech,saveDialogueHistory}from'@/utils/api.js';import{getAudioSettings}from'@/utils/learning-settings.js';
const PASS_SCORE=70;
const DEFAULT_SCENES=[{id:1,icon:'🍽️',name:'餐厅点餐',description:'练习点餐、饮品和结账表达'},{id:2,icon:'🗺️',name:'问路指路',description:'练习询问地点和确认路线'},{id:3,icon:'🛒',name:'购物消费',description:'练习询价、试穿和付款表达'},{id:4,icon:'💼',name:'职场寒暄',description:'练习问候、近况和工作交流'}];
const ROUNDS={
'餐厅点餐':[{prompt:'Good evening. Are you ready to order?',promptZh:'晚上好，您准备好点餐了吗？',taskZh:'是的，我想要一份牛排',answer:'Yes, I would like a steak, please.'},{prompt:'What would you like to drink?',promptZh:'您想喝点什么？',taskZh:'请给我一杯橙汁',answer:'I would like a glass of orange juice, please.'},{prompt:'Would you like anything else?',promptZh:'您还需要别的吗？',taskZh:'不用了，请给我账单',answer:'No, thank you. Could I have the bill, please?'}],
'问路指路':[{prompt:'Hello. Can I help you?',promptZh:'你好，需要帮助吗？',taskZh:'请问最近的地铁站在哪里',answer:'Excuse me, where is the nearest subway station?'},{prompt:'Go straight and turn left at the traffic lights.',promptZh:'直走，在红绿灯处左转。',taskZh:'询问走路需要多长时间',answer:'How long does it take to walk there?'},{prompt:'It takes about ten minutes.',promptZh:'大约需要十分钟。',taskZh:'感谢对方的帮助',answer:'Thank you very much for your help.'}],
'购物消费':[{prompt:'Welcome. What are you looking for today?',promptZh:'欢迎光临，您今天想买什么？',taskZh:'我在找一件蓝色衬衫',answer:'I am looking for a blue shirt.'},{prompt:'Would you like to try this one?',promptZh:'您想试试这件吗？',taskZh:'询问是否有大一号',answer:'Do you have this in a larger size?'},{prompt:'Yes, here you are.',promptZh:'有的，给您。',taskZh:'表示决定购买',answer:'It fits well. I will take it.'}],
'职场寒暄':[{prompt:'Good morning. How was your weekend?',promptZh:'早上好，周末过得怎么样？',taskZh:'周末很好，并感谢询问',answer:'It was great, thank you for asking.'},{prompt:'Are you busy with the new project?',promptZh:'你最近在忙新项目吗？',taskZh:'表示正在准备下午的会议',answer:'Yes, I am preparing for the meeting this afternoon.'},{prompt:'Let me know if you need any help.',promptZh:'如果需要帮助请告诉我。',taskZh:'感谢并表示有需要会告知',answer:'Thank you. I will let you know if I need help.'}]};
export default{data(){return{loading:true,scenes:[],activeScene:null,rounds:[],currentIndex:0,isRecording:false,evaluating:false,recorder:null,recordStartedAt:0,recordTimer:null,autoTimer:null,recordSeconds:0,hasResult:false,passed:false,score:0,feedback:'',scores:[],completed:false,audio:null,voiceType:1,leaving:false,startedAt:0}},computed:{currentRound(){return this.rounds[this.currentIndex]||{}},progress(){return this.rounds.length?(this.currentIndex+(this.passed?1:0))/this.rounds.length*100:0},averageScore(){return this.scores.length?Math.round(this.scores.reduce((a,b)=>a+b,0)/this.scores.length):0},summarySuggestion(){return this.averageScore>=90?'表达自然流畅，可以尝试更自由的表达。':this.averageScore>=80?'整体表现很好，继续注意句子节奏和语调。':'已完成练习，建议重听原句并加强易错词发音。'}},async onLoad(){const s=await getAudioSettings();this.voiceType=s.voiceType;this.initRecorder();this.loadScenes()},onUnload(){this.leaving=true;this.clearTimers();if(this.isRecording&&this.recorder)this.recorder.stop();if(this.audio)this.audio.destroy()},methods:{async loadScenes(){this.loading=true;try{const rows=await request('/scene/list');this.scenes=rows?.length?rows:DEFAULT_SCENES}catch(_){this.scenes=DEFAULT_SCENES}finally{this.loading=false}},startScene(scene){this.activeScene=scene;this.rounds=ROUNDS[scene.name]||ROUNDS['餐厅点餐'];this.currentIndex=0;this.scores=[];this.completed=false;this.startedAt=Date.now();this.resetRound()},resetRound(){this.hasResult=false;this.passed=false;this.score=0;this.feedback='';this.recordSeconds=0},initRecorder(){this.recorder=uni.getRecorderManager();this.recorder.onStop(r=>{this.isRecording=false;this.clearTimers();if(this.leaving)return;if(Date.now()-this.recordStartedAt<1000)return uni.showToast({title:'录音太短，请说完整句话',icon:'none'});if(!r.tempFilePath)return uni.showToast({title:'未获取到录音，请重试',icon:'none'});this.evaluate(r.tempFilePath)});this.recorder.onError(()=>{this.isRecording=false;this.evaluating=false;this.clearTimers();uni.showToast({title:'录音失败，请检查麦克风权限',icon:'none'})})},clearTimers(){if(this.recordTimer){clearInterval(this.recordTimer);this.recordTimer=null}if(this.autoTimer){clearTimeout(this.autoTimer);this.autoTimer=null}},ensurePermission(){return new Promise(resolve=>uni.getSetting({success:s=>{const v=s.authSetting['scope.record'];if(v===true)return resolve(true);if(v===false)return uni.showModal({title:'需要麦克风权限',content:'请允许使用麦克风后再练习。',confirmText:'去设置',success:r=>r.confirm?uni.openSetting({success:x=>resolve(x.authSetting['scope.record']===true),fail:()=>resolve(false)}):resolve(false)});uni.authorize({scope:'scope.record',success:()=>resolve(true),fail:()=>resolve(false)})},fail:()=>resolve(false)}))},async toggleRecord(){if(this.evaluating)return;if(this.isRecording){this.recorder.stop();return}if(!await this.ensurePermission())return;this.resetRound();this.isRecording=true;this.recordStartedAt=Date.now();this.recorder.start({duration:20000,sampleRate:16000,numberOfChannels:1,encodeBitRate:48000,format:'mp3'});this.recordTimer=setInterval(()=>this.recordSeconds=Math.floor((Date.now()-this.recordStartedAt)/1000),250);this.autoTimer=setTimeout(()=>{if(this.isRecording)this.recorder.stop()},20000)},evaluate(path){this.evaluating=true;uni.getFileSystemManager().readFile({filePath:path,encoding:'base64',success:async f=>{try{const r=await evaluateSpeech(f.data,this.currentRound.answer,'read_sentence','mp3');this.score=Number(r?.score||0);this.feedback=r?.feedback||'';this.hasResult=true;this.passed=this.score>=PASS_SCORE}catch(e){uni.showToast({title:e.message||'评分失败，请重试',icon:'none'})}finally{this.evaluating=false}},fail:()=>{this.evaluating=false;uni.showToast({title:'读取录音失败',icon:'none'})}})},nextRound(){if(!this.passed)return;this.scores.push(this.score);if(this.currentIndex+1<this.rounds.length){this.currentIndex++;this.resetRound();this.playText(this.currentRound.prompt)}else this.finishScene()},async finishScene(){this.completed=true;const messages=this.rounds.map((r,i)=>({prompt:r.prompt,answer:r.answer,score:this.scores[i]||0}));try{await saveDialogueHistory({scene_name:this.activeScene.name,scene_icon:this.activeScene.icon,messages,average_score:this.averageScore,duration:Math.max(1,Math.round((Date.now()-this.startedAt)/60000))})}catch(_){uni.showToast({title:'成绩暂未同步，已保留结果',icon:'none'})}},playText(text){if(this.audio)this.audio.destroy();const a=uni.createInnerAudioContext();a.src=`https://dict.youdao.com/dictvoice?type=${this.voiceType}&audio=${encodeURIComponent(text)}`;a.onCanplay(()=>a.play());a.onError(()=>uni.showToast({title:'音频播放失败',icon:'none'}));this.audio=a},exitPractice(){uni.showModal({title:'退出当前场景？',content:'未完成的进度不会保存。',success:r=>{if(r.confirm)this.backToScenes()}})},backToScenes(){this.clearTimers();this.activeScene=null;this.completed=false;this.resetRound()},goBack(){uni.navigateBack()}}}
</script>
<style>
.page{box-sizing:border-box;min-height:100vh;padding:24rpx 22rpx 55rpx;background:linear-gradient(180deg,#eef5f6 0,#f7f5f0 420rpx)}.hero{padding:28rpx;border-radius:26rpx;background:#1f3a5f;color:#fff;box-shadow:0 13rpx 30rpx rgba(31,58,95,.18)}.title{display:block;font-size:40rpx;font-weight:800}.subtitle{display:block;margin-top:7rpx;font-size:22rpx;color:rgba(255,255,255,.72)}.section-heading{display:flex;align-items:center;justify-content:space-between;margin:31rpx 5rpx 15rpx}.section-title{font-size:32rpx;font-weight:800;color:#213f61}.section-tip{font-size:21rpx;color:#8e9aa4}.scene-list{display:flex;flex-direction:column;gap:13rpx}.scene-card{display:flex;align-items:center;padding:23rpx 21rpx;border-radius:22rpx;background:#fff;box-shadow:0 7rpx 21rpx rgba(35,63,87,.07)}.scene-icon{display:flex;align-items:center;justify-content:center;width:68rpx;height:68rpx;border-radius:19rpx;background:#e6f5f2;font-size:33rpx}.scene-info{flex:1;margin-left:17rpx}.scene-name{display:block;font-size:28rpx;font-weight:800;color:#294866}.scene-desc{display:block;margin-top:5rpx;font-size:22rpx;color:#8d99a3}.scene-action{font-size:22rpx;font-weight:700;color:#0d9488}.empty{padding:100rpx 20rpx;text-align:center;color:#8b969f}.practice-head{display:flex;align-items:center;justify-content:space-between}.scene-kicker{display:block;font-size:32rpx;font-weight:800;color:#1f3a5f}.round{display:block;margin-top:5rpx;font-size:22rpx;color:#84919c}.exit{font-size:23rpx;color:#8e98a1}.progress{height:10rpx;margin:20rpx 0;border-radius:10rpx;background:#dfe7e9;overflow:hidden}.progress-fill{height:100%;background:#0d9488}.conversation-card,.task-card{margin-top:18rpx;padding:25rpx;border-radius:23rpx;background:#fff;box-shadow:0 7rpx 22rpx rgba(35,63,87,.08)}.speaker-row{display:flex;align-items:center;gap:10rpx;font-size:22rpx;color:#7d8994}.avatar{display:flex;align-items:center;justify-content:center;width:50rpx;height:50rpx;border-radius:15rpx;background:#edf3f7}.prompt-en{display:block;margin-top:20rpx;font-size:32rpx;font-weight:800;line-height:1.45;color:#294866}.prompt-zh{display:block;margin-top:8rpx;font-size:23rpx;color:#83909a}.play-button{display:inline-flex;margin-top:21rpx;padding:13rpx 20rpx;border-radius:28rpx;background:#e6f6f3;color:#0d9488;font-size:22rpx}.task-label{display:block;font-size:22rpx;font-weight:700;color:#0d9488}.task-zh{display:block;margin-top:13rpx;font-size:28rpx;font-weight:800;color:#294866}.answer-hint{display:block;margin-top:13rpx;padding:16rpx;border-radius:14rpx;background:#f4f7f8;font-size:23rpx;line-height:1.5;color:#687986}.record-button{display:flex;justify-content:center;margin-top:22rpx;padding:22rpx;border-radius:17rpx;background:#1f3a5f;color:#fff;font-size:27rpx;font-weight:800}.record-button.recording{background:#d54d4d}.record-button.evaluating{background:#718292}.record-tip{display:block;margin-top:10rpx;text-align:center;font-size:21rpx;color:#d35454}.result{margin-top:18rpx;padding:18rpx;border-radius:15rpx}.result.passed{background:#edf9f5;color:#0d8d80}.result.failed{background:#fff3f1;color:#c95048}.result-top{display:flex;justify-content:space-between;font-size:25rpx;font-weight:800}.score{font-size:31rpx}.feedback{display:block;margin-top:7rpx;font-size:22rpx;color:#677985}.next-button,.primary,.secondary{margin-top:20rpx;border:0;border-radius:16rpx;background:#0d9488;color:#fff;font-size:27rpx}.secondary{background:#edf2f5;color:#294866}.complete-card{margin-top:80rpx;padding:45rpx 28rpx;border-radius:25rpx;background:#fff;text-align:center}.complete-icon{font-size:72rpx}.complete-title{display:block;margin-top:12rpx;font-size:40rpx;font-weight:800;color:#1f3a5f}.complete-scene{display:block;margin-top:8rpx;font-size:25rpx;color:#788793}.summary{display:flex;margin-top:27rpx;padding:20rpx;border-radius:17rpx;background:#f3f7f8}.summary view{flex:1}.summary text:first-child{display:block;font-size:35rpx;font-weight:800;color:#0d9488}.summary text:last-child{display:block;font-size:21rpx;color:#83909a}.suggestion{display:block;margin-top:22rpx;font-size:23rpx;line-height:1.6;color:#657783}
</style>
